=\"3\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"payamt\" perm=\"2\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"2\"></wf:fieldPerm>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"attach\",\"print\"]},\"fieldCheck\":{\"script\":\"eeramt:required\"}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"></sequenceFlow>\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:assignee=\"${wfMiAssignee}\">\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"18\" objId=\"\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"1\"></wf:fieldPerm>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Create\"]}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Department\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"></sequenceFlow>\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\n      <extensionElements>\n        <wf:node nodeType=\"7\"></wf:node>\n      </extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\n      <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${eeramt <= 5000}]]></conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"></sequenceFlow>\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:assignee=\"${wfMiAssignee}\">\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000026\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Department\",\"Task_Create\"]}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Vice\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"></sequenceFlow>\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\n      <extensionElements>\n        <wf:node nodeType=\"7\"></wf:node>\n      </extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Large\" name=\"大额&gt;20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\n      <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${eeramt > 20000}]]></conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"></sequenceFlow>\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:assignee=\"${wfMiAssignee}\">\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000027\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Vice\",\"Task_Department\",\"Task_Create\"]}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_GM\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"></sequenceFlow>\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:assignee=\"${wfMiAssignee}\">\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000028\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_FinReview\",\"Task_Create\"]}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_FinManager\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"></sequenceFlow>\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:assignee=\"${wfMiAssignee}\">\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000029\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"dt1\" field=\"ablebudgetamt\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"dt3\" field=\"hrmbankaccount\" perm=\"1\"></wf:fieldPerm>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"circulate\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Create\",\"Task_Department\",\"Task_Vice\",\"Task_GM\",\"Task_FinManager\"]},\"exceptionHandle\":{\"enabled\":true,\"way\":1,\"targetNodeKey\":\"Task_FinManager\",\"mode\":1}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_FinReview\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_Fin\" name=\"财务通过\" sourceRef=\"Task_FinReview\" targetRef=\"Gateway_Pay\"></sequenceFlow>\n    <exclusiveGateway id=\"Gateway_Pay\" name=\"是否需付款\" default=\"F_NoPay\">\n      <extensionElements>\n        <wf:node nodeType=\"7\"></wf:node>\n      </extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Pay\" name=\"需付款\" sourceRef=\"Gateway_Pay\" targetRef=\"Task_Cashier\">\n      <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${payamt > 0}]]></conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_NoPay\" name=\"无需付款(default)\" sourceRef=\"Gateway_Pay\" targetRef=\"EndEvent_Archive\"></sequenceFlow>\n    <userTask id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:assignee=\"${wfMiAssignee}\">\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000030\" signOrder=\"0\" bhxj=\"0\"></wf:operator>\n          <extJson><![CDATA[{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"attach\",\"opinion\",\"print\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_FinReview\",\"Task_Create\"]}}}]]></extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Cashier\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"></sequenceFlow>\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\n      <extensionElements>\n        <wf:node nodeType=\"3\"></wf:node>\n      </extensionElements>\n    </endEvent>\n  </process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_travel_reimburse_approval_v2\">\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval_v2\" id=\"BPMNPlane_travel_reimburse_approval_v2\">\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"BPMNShape_StartEvent_1\">\n        <omgdc:Bounds height=\"30.0\" width=\"30.0\" x=\"60.0\" y=\"245.0\"></omgdc:Bounds>\n      </bpmndi:BPMNShape>\n      <