k id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:assignee=\"${wfMiAssignee}\">\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"4000000030\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:extJson><![CDATA[{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}]]></wf:extJson>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Cashier\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"></sequenceFlow>\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\n      <extensionElements>\n        <wf:node nodeType=\"3\">\n          <wf:extJson><![CDATA[{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}]]></wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </endEvent>\n  </process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_travel_reimburse_approval_v2\">\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval_v2\" id=\"BPMNPlane_travel_reimburse_approval_v2\">\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"BPMNShape_StartEvent_1\">\n        <omgdc:Bounds height=\"30.0\" width=\"30.0\" x=\"60.0\" y=\"245.0\"></omgdc:Bounds>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Create\" id=\"BPMNShape_Task_Create\">\n        <omgdc:Bounds height=\"80.0\" width=\"120.0\" x=\"130.0\" y=\"220.0\"></omgdc:Bounds>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Department\" id=\"BPMNShape_Task_Department\">\n        <omgdc:Bounds height=\"80.0\" width=\"120.0\" x=\"300.0\" 