INSERT INTO `act_ge_bytearray` VALUES ('350002',1,'odoc_fawen.bpmn20.xml','350001',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:flowable=\"http://flowable.org/bpmn\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:wf=\"http://www.springblade.org/workflow\" typeLanguage=\"http://www.w3.org/2001/XMLSchema\" expressionLanguage=\"http://www.w3.org/1999/XPath\" targetNamespace=\"http://www.springblade.org/workflow\" xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\n  <process id=\"odoc_fawen\" name=\"发文流程\" isExecutable=\"true\">\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"></startEvent>\n    <sequenceFlow id=\"Flow_1\" name=\"提交\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"></sequenceFlow>\n    <userTask id=\"Task_Create\" name=\"拟稿\" flowable:assignee=\"${initiator}\" flowable:formKey=\"odoc_fawen_form\">\n      <documentation>创建节点:拟稿人填写公文表单并编辑正文(docId);title/urgency/secretLevel/topicType/mainSend/copyTo/issueDate 必填或可编辑,number 暂隐藏,docId 必填。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"17\" objId=\"\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"urgency\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"secretLevel\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"topicType\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"mainSend\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"copyTo\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"issueDate\" perm=\"0\" required=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"0\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"zw\" perm=\"3\" required=\"1\"></wf:fieldPerm>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_2\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_DeptReview\"></sequenceFlow>\n    <userTask id=\"Task_DeptReview\" name=\"部门核稿\" flowable:assignee=\"${wfMiAssignee}\" flowable:candidateGroups=\"role_dept_leader\">\n      <documentation>部门负责人核稿:正文与表单只读,提出修改意见可退回拟稿。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"18\" objId=\"\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:operator opType=\"2\" objId=\"role_dept_leader\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"urgency\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"secretLevel\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"topicType\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"mainSend\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"copyTo\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"issueDate\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"0\"></wf:fieldPerm>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"></wf:timeout>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_DeptReview\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"Flow_3\" name=\"通过\" sourceRef=\"Task_DeptReview\" targetRef=\"Task_Taohong\"></sequenceFlow>\n    <userTask id=\"Task_Taohong\" name=\"排版套红\" flowable:assignee=\"${wfMiAssignee}\" flowable:candidateGroups=\"role_wenmi\">\n      <documentation>文书/文秘排版套红:WfNodeMustDoActionExecutor 按 wf_odoc_process_set.taohong_node_key == Task_Taohong 且 must_taohong=1 强制提交前完成套红(has_used_templet=1),否则拦截。正文只读,套红模板选取。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_wenmi\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\"></wf:fieldPerm>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Taohong\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"Flow_4\" name=\"通过\" sourceRef=\"Task_Taohong\" targetRef=\"Task_Countersign\"></sequenceFlow>\n    <userTask id=\"Task_Countersign\" name=\"会签\" flowable:assignee=\"${wfMiAssignee}\" flowable:candidateGroups=\"role_countersign\">\n      <documentation>相关职能部门会签:同一节点多角色并行审批,全部通过才推进。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"1\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_countersign\" bhxj=\"0\" signOrder=\"1\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\"></wf:fieldPerm>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Countersign\" flowable:elementVariable=\"wfMiAssignee\"></multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"Flow_5\" name=\"通过\" sourceRef=\"Task_Countersign\" targetRef=\"Task_Sign\"></sequenceFlow>\n    <userTask id=\"Task_Sign\" name=\"签发\" flowable:assignee=\"${wfMiAssignee}\" flowable:candidateGroups=\"role_fgld\">\n      <documentation>分管领导签发:签发环节触发文号取号(WfNumberAssignListener 在签发出口取号写 number 字段)。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_fgld\" bhxj=\"0\" signOrder=\"0\"></wf:operator>\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\"></wf:fieldPerm>\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\"></wf:fieldPerm>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"2880\" actionWay=\"remind\" remindTypes=\"sys\"></wf:timeout>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_Task_Sign\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>