DROP TABLE IF EXISTS `blade_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_message` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) NOT NULL COMMENT '租户ID',
  `session_id` bigint NOT NULL COMMENT '会话ID',
  `sender_id` bigint NOT NULL COMMENT '发送人（blade_user.id）',
  `content_type` int NOT NULL DEFAULT '1' COMMENT '内容类型 1文本 2富文本 3附件 4流程引用',
  `category` int NOT NULL DEFAULT '1' COMMENT '消息分类 1=聊天 2=流程通知',
  `biz_state` int DEFAULT NULL COMMENT '通知业务状态 NULL=待处理 1=已处理 2=已办结',
  `content` varchar(2000) DEFAULT NULL COMMENT '内容',
  `quote_message_id` bigint DEFAULT NULL COMMENT '引用消息ID',
  `biz_ref_type` varchar(30) DEFAULT NULL COMMENT '业务引用类型（WF_INSTANCE/WF_TASK）',
  `biz_ref_id` varchar(64) DEFAULT NULL COMMENT '业务引用ID（字符串防精度丢失）',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态 1=SENT',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_user` bigint DEFAULT NULL COMMENT '更新人',
  `is_deleted` int DEFAULT NULL COMMENT '是否已删除',
  PRIMARY KEY (`id`),
  KEY `idx_blade_message_session` (`session_id`),
  KEY `idx_blade_message_tenant` (`tenant_id`),
  KEY `idx_blade_message_biz_ref` (`biz_ref_type`,`biz_ref_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息主体';
/*!40101 SET character_set_client = @saved_cs_client */;

