DROP TABLE IF EXISTS `doc_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_detail` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) DEFAULT NULL COMMENT '租户ID',
  `sec_category_id` bigint DEFAULT NULL COMMENT '所属目录',
  `doc_subject` varchar(500) DEFAULT NULL COMMENT '文档标题',
  `doc_status` int DEFAULT NULL COMMENT '文档状态 0草稿/1生效/2生效/3审批中/4退回/5归档/6待发布/7失效/8作废/9流程草稿',
  `doc_edition_id` bigint DEFAULT NULL COMMENT '版本族ID',
  `doc_edition` int DEFAULT NULL COMMENT '版次号',
  `is_history` int DEFAULT '0' COMMENT '是否历史版本',
  `main_file_id` bigint DEFAULT NULL COMMENT '正文文件ID',
  `content_id` bigint DEFAULT NULL COMMENT '正文内容ID',
  `sub_company_id` bigint DEFAULT NULL COMMENT '所属分部(DataScope隔离维度)',
  `is_top` int DEFAULT '0' COMMENT '是否置顶',
  `is_valid` int DEFAULT '1' COMMENT '是否有效',
  `selected_pub_mould_id` bigint DEFAULT NULL COMMENT '发布选用的显示模板ID',
  `check_out_status` int DEFAULT '0' COMMENT '签出状态 0未签出 1已签出',
  `check_out_user_id` bigint DEFAULT NULL COMMENT '签出人',
  `create_user` bigint DEFAULT NULL,
  `create_dept` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_user` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `status` int DEFAULT '1',
  `is_deleted` int DEFAULT '0',
  `approve_inst_id` bigint DEFAULT NULL COMMENT '审批流程实例ID(发起审批时回填)',
  PRIMARY KEY (`id`),
