  `status` int NOT NULL DEFAULT '1' COMMENT '状态:1正常 0禁用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_inst_node` (`inst_id`,`node_key`),
  KEY `idx_inst_time` (`inst_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2117206468097785859 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='表单数据快照';
