--
-- Table structure for table `wf_instance`
--

DROP TABLE IF EXISTS `wf_instance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_instance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `engine_inst_id` varchar(64) DEFAULT NULL COMMENT '引擎实例ID（Flowable PROC_INST_ID_），弱关联，不依赖 ACT_* 表；草稿等未进引擎的实例为 NULL（唯一索引允许多个 NULL）',
  `def_id` bigint unsigned NOT NULL COMMENT '流程定义ID',
  `form_id` bigint DEFAULT NULL COMMENT '表单ID（workflow_bill.id），可空',
  `data_id` bigint NOT NULL COMMENT '业务数据ID（formtable_main_{id}.id）',
  `title` varchar(400) NOT NULL DEFAULT '' COMMENT '流程标题',
  `biz_key` varchar(128) NOT NULL COMMENT '业务主键 formId:dataId，便于反查',
  `current_node_key` varchar(64) NOT NULL DEFAULT '' COMMENT '当前节点',
  `starter` bigint NOT NULL COMMENT '发起人',
  `start_time` datetime NOT NULL COMMENT '发起时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `urgency` tinyint NOT NULL DEFAULT '0' COMMENT '紧急程度 0/1/2（对齐 requestlevel）',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '父流程实例（子流程）',
  `tenant_id` varchar(32) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '0' COMMENT '0运行中 1通过 2不通过 3撤销 4暂停（对齐 ecology currentstatus 语义）',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `is_test` tinyint NOT NULL DEFAULT '0' COMMENT '测试态标记 1=测试产生的实例/数据',
  `business_row_ready` tinyint DEFAULT NULL COMMENT 'L3自检：业务数据行已就绪 1=有对应行 0=仅占位 NULL=未自检',
  `request_id_bound` tinyint DEFAULT NULL COMMENT 'L3自检：业务行 request_id 已回填 1=是 0=否 NULL=无需/未自检',
  `engine_deployment_matched` tinyint DEFAULT NULL COMMENT 'L3自检：引擎 latest 部署 == 定义 deployment_id 1=一致 0=被顶替 NULL=未知',
  `test_deployment_id` varchar(64) DEFAULT NULL COMMENT '测试临时部署ID（清理时级联卸载）',
  `proc_def_id` varchar(64) DEFAULT NULL COMMENT '本实例实际使用的 Flowable processDefinitionId（审计/回滚依据）',
  `is_gray` tinyint NOT NULL DEFAULT '0' COMMENT '灰度实例 1=走灰度版本 0=正式版本',
  `pending_status` tinyint DEFAULT NULL COMMENT '期望终态(intent)：由业务在引擎终结前写入，供 PROCESS_CANCELLED 事件派生（1通过/2不通过/3撤销）；应用后清空',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_key` (`biz_key`),
  UNIQUE KEY `uk_engine_inst` (`engine_inst_id`),
  KEY `idx_status_start` (`status`,`start_time`),
  KEY `idx_starter_status` (`starter`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2117206468097785858 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程实例';
