--
-- Table structure for table `wf_matrix_field`
--

DROP TABLE IF EXISTS `wf_matrix_field`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_matrix_field` (
  `id` bigint NOT NULL COMMENT '主键（雪花）',
  `tenant_id` varchar(50) NOT NULL COMMENT '租户ID',
  `matrix_id` bigint NOT NULL COMMENT '所属矩阵 wf_matrix.id',
  `field_key` varchar(50) NOT NULL COMMENT '字段唯一键（应用层唯一，用于 data_json 的 key）',
  `display_name` varchar(100) NOT NULL COMMENT '字段显示名',
  `browser_type` int DEFAULT NULL COMMENT '浏览按钮类型（对齐E9 browsertypeid：4/57部门 164/194分部 17多人力资源 1人力资源）',
