--
-- Table structure for table `wf_node_timeout`
--

DROP TABLE IF EXISTS `wf_node_timeout`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_node_timeout` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` varchar(12) NOT NULL DEFAULT '000000' COMMENT '租户',
  `def_id` bigint NOT NULL COMMENT '流程定义 ID',
  `node_key` varchar(64) NOT NULL COMMENT '节点 Key',
  `seq` int NOT NULL DEFAULT '0' COMMENT '排序（升序执行）',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用 1=是 0=否',
  `start_type` tinyint NOT NULL DEFAULT '1' COMMENT '起算方式 1=节点到达(收到待办) 2=表单时间字段',
  `start_field` varchar(64) DEFAULT NULL COMMENT '起算=表单时间字段时的字段名',
  `duration_min` int DEFAULT NULL COMMENT '截止=相对时长时的分钟数',
  `end_type` tinyint NOT NULL DEFAULT '1' COMMENT '截止方式 1=相对(起算+时长) 2=固定时刻(HH:mm) 3=表单时间字段',
  `end_fixed_time` varchar(8) DEFAULT NULL COMMENT '截止=固定时刻时的 HH:mm',
  `end_field` varchar(64) DEFAULT NULL COMMENT '截止=表单时间字段时的字段名',
  `action_way` varchar(16) NOT NULL DEFAULT 'autoApprove' COMMENT '超时动作 autoApprove/forward/assign/remind',
  `target_node_key` varchar(64) DEFAULT NULL COMMENT '动作=forward 时的目标节点（扩展位，当前按 autoApprove 语义流转）',
  `operator_ids` varchar(255) DEFAULT NULL COMMENT '动作=assign 时的指定操作者（人力资源 ID 逗号分隔）',
  `opinion` varchar(255) DEFAULT NULL COMMENT '动作意见',
  `remind_types` varchar(32) DEFAULT NULL COMMENT '提醒方式 sys=流程提醒 ml=短信 sm=邮件（逗号分隔）',
  `remind_before_operator` tinyint NOT NULL DEFAULT '0' COMMENT '提醒对象：节点当前处理人 1=是 0=否',
  `remind_persons` varchar(255) DEFAULT NULL COMMENT '提醒对象：指定人员（人力资源 ID 逗号分隔）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态:1正常 0禁用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_node_timeout_def_node` (`def_id`,`node_key`,`seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='节点超时规则（多条，对齐泛微超时设置）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wf_node_timeout`
--

