  KEY `idx_wf_odoc_doc_test` (`is_test`,`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公文正文文档';
