--
-- Table structure for table `wf_odoc_sign_flow`
--

DROP TABLE IF EXISTS `wf_odoc_sign_flow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_odoc_sign_flow` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(12) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `inst_id` bigint NOT NULL COMMENT '流程实例ID',
  `doc_id` bigint NOT NULL COMMENT '公文正文ID',
  `src_version_id` bigint DEFAULT NULL COMMENT '发起签署时的正文版本ID（原文版本，归档后仍保留）',
  `esign_file_id` varchar(64) DEFAULT NULL COMMENT 'e签宝文件ID',
  `flow_id` varchar(64) DEFAULT NULL COMMENT 'e签宝签署流程ID',
  `biz_num` varchar(64) DEFAULT NULL COMMENT '业务流水号(customBizNum)，发起幂等键',
  `title` varchar(500) DEFAULT NULL COMMENT '签署标题',
  `seal_mode` int NOT NULL DEFAULT '0' COMMENT '用印方式 0自研印章(本地) 1e签宝印章（D2 并存）',
  `sign_status` int NOT NULL DEFAULT '0' COMMENT '签署状态 0待发起 1进行中 2已完成 3已撤销 4已拒签 5已过期 9失败',
  `sign_result` int DEFAULT NULL COMMENT 'e签宝 signResult（2=签署完成）',
  `archive_version_id` bigint DEFAULT NULL COMMENT '归档后回写的新版本ID',
  `antchain_info` varchar(1000) DEFAULT NULL COMMENT '区块链存证信息(JSON)',
  `error_msg` varchar(1000) DEFAULT NULL COMMENT '失败原因',
  `notify_count` int NOT NULL DEFAULT '0' COMMENT '回调次数',
  `last_notify_time` datetime DEFAULT NULL COMMENT '最近回调时间',
  `last_query_time` datetime DEFAULT NULL COMMENT '最近补偿查询时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除 0未删 1已删',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态:1正常 0禁用',
  `node_key` varchar(64) DEFAULT NULL COMMENT '签章节点Key',
  `task_id` bigint DEFAULT NULL COMMENT '业务待办ID(wf_task.id)',
  `engine_task_id` varchar(64) DEFAULT NULL COMMENT '引擎任务ID(推进时completeTask)',
  `operator` bigint DEFAULT NULL COMMENT '提交人(推进时作为currentOperator)',
  `vars_json` text COMMENT '提交变量JSON(推进时回填引擎)',
  `advance_status` int NOT NULL DEFAULT '0' COMMENT '推进状态 0待推进 1推进中 2已推进 3已终止(拒签/过期)',
  `advance_time` datetime DEFAULT NULL COMMENT '推进完成时间',
  `advance_msg` varchar(500) DEFAULT NULL COMMENT '推进结果/失败原因',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_wosf_flow_id` (`flow_id`),
  UNIQUE KEY `uk_wosf_biz_num` (`biz_num`),
  KEY `idx_wosf_inst` (`inst_id`),
  KEY `idx_wosf_doc` (`doc_id`),
  KEY `idx_wosf_sign_status` (`sign_status`),
  KEY `idx_wosf_advance` (`sign_status`,`advance_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='公文-e签宝签署流程';
/*!40101 SET character_set_client = @saved_cs_client */;

