/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_process_definition` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `proc_key` varchar(64) NOT NULL COMMENT '引擎流程Key（= BPMN process id）',
  `form_id` bigint DEFAULT NULL COMMENT '关联 workflow_bill.id（表单），可空',
  `name` varchar(200) NOT NULL COMMENT '流程名称',
  `bpmn_xml` mediumtext COMMENT 'BPMN 2.0 流程定义 XML（bpmn-js 画布产出，部署时下发引擎）',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  `active_version_id` bigint unsigned DEFAULT NULL COMMENT '版本组锚点：指向当前激活版本的 defId；首版=自身id，NULL=单版本流程（组=自身）',
  `deployment_id` varchar(64) DEFAULT NULL COMMENT '最近一次正式部署的引擎部署ID（ACT_RE_DEPLOYMENT.ID_）；NULL=尚未正式部署/未落库',
  `is_free` tinyint NOT NULL DEFAULT '0' COMMENT '是否自由流程',
  `free_wf_type` tinyint DEFAULT NULL COMMENT '自由流程类型：1简易 2高级',
  `type` varchar(64) DEFAULT NULL COMMENT '路径类型（对齐 ecology path_type 字典 code）',
  `form_type` tinyint DEFAULT NULL COMMENT '对应表单类型：0自定义表单 1系统表单',
  `description` varchar(500) DEFAULT NULL COMMENT '路径描述',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '显示顺序',
  `tenant_id` varchar(32) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '0' COMMENT '0草稿 1已发布 2停用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除:1已删 0未删',
  `proc_def_id` varchar(64) DEFAULT NULL COMMENT '激活版本对应的 Flowable processDefinitionId（ACT_RE_PROCDEF.ID_）',
  `draft_revision` bigint NOT NULL DEFAULT '0' COMMENT '草稿修订号（D15/R11）：saveBpmn 原子递增；客户端保存携带 baseRevision 做乐观并发校验',
  `test_proc_def_id` varchar(64) DEFAULT NULL COMMENT '测试态最近一次测试部署的 processDefinitionId（procKey__test）；配置面板在 status=3 时优先读它；NULL=从未测试部署',
  `archive_manage` text COMMENT '归档管理策略JSON：强制归档/可归档节点范围/归档后可强制收回/归档后可流程干预；NULL=未配置（既有能力保持开启，全新能力默认关闭）',
  `recall_manage` text COMMENT '撤回管理策略JSON：允许强制收回/允许监控回退/提醒选择总闸/强制收回落点范围；NULL=未配置（既有能力保持开启，提醒总闸默认关闭）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proc_key_version` (`proc_key`,`version`,`is_deleted`),
  KEY `idx_form_status` (`form_id`,`status`),
  KEY `idx_active_version` (`active_version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2117206127369306115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程定义';
