gnOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"17\" objId=\"\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"urgency\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"secretLevel\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"topicType\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"mainSend\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"copyTo\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"issueDate\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"zw\" perm=\"3\" required=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_2\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_DeptReview\" />\n    <userTask id=\"Task_DeptReview\" name=\"部门核稿\" flowable:candidateGroups=\"role_dept_leader\">\n      <documentation>部门负责人核稿:正文与表单只读,提出修改意见可退回拟稿。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"18\" objId=\"\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:operator opType=\"2\" objId=\"role_dept_leader\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"urgency\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"secretLevel\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"topicType\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"mainSend\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"copyTo\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"issueDate\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"0\" />\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_3\" name=\"通过\" sourceRef=\"Task_DeptReview\" targetRef=\"Task_Taohong\" />\n    <userTask id=\"Task_Taohong\" name=\"排版套红\" flowable:candidateGroups=\"role_wenmi\">\n      <documentation>文书/文秘排版套红:WfNodeMustDoActionExecutor 按 wf_odoc_process_set.taohong_node_key == Task_Taohong 且 must_taohong=1 强制提交前完成套红(has_used_templet=1),否则拦截。正文只读,套红模板选取。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_wenmi\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_4\" name=\"通过\" sourceRef=\"Task_Taohong\" targetRef=\"Task_Countersign\" />\n    <userTask id=\"Task_Countersign\" name=\"会签\" flowable:candidateGroups=\"role_countersign\">\n      <documentation>相关职能部门会签:同一节点多角色并行审批,全部通过才推进。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"1\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_countersign\" bhxj=\"0\" signOrder=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_5\" name=\"通过\" sourceRef=\"Task_Countersign\" targetRef=\"Task_Sign\" />\n    <userTask id=\"Task_Sign\" name=\"签发\" flowable:candidateGroups=\"role_fgld\">\n      <documentation>分管领导签发:签发环节触发文号取号(WfNumberAssignListener 在签发出口取号写 number 字段)。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_fgld\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\" />\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"2880\" actionWay=\"remind\" remindTypes=\"sys\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_6\" name=\"通过\" sourceRef=\"Task_Sign\" targetRef=\"Task_Seal\" />\n    <userTask id=\"Task_Seal\" name=\"用印签章\" flowable:candidateGroups=\"role_seal\">\n      <documentation>用印/电子签章:wf_odoc_process_set.seal_required=1 时 WfNodeMustDoActionExecutor 强制提交前完成签章。L1 不装配签章 SPI 时此节点仅作普通用印登记。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_seal\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_7\" name=\"通过\" sourceRef=\"Task_Seal\" targetRef=\"Task_Finalize\" />\n    <userTask id=\"Task_Finalize\" name=\"定稿编号\" flowable:candidateGroups=\"role_wenmi\">\n      <documentation>定稿:正文 frozen(is_final=1,doc_status=1),number 可编辑/确认,生成正式版式源 docx。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_wenmi\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"number\" perm=\"2\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_8\" name=\"通过\" sourceRef=\"Task_Finalize\" targetRef=\"Task_Layout\" />\n    <userTask id=\"Task_Layout\" name=\"转版式\" flowable:candidateGroups=\"role_wenmi\">\n      <documentation>转版式:按 wf_odoc_process_set.layout_format 同一 to-layout 接口转 PDF(12)/OFD(13);元数据注入 wf_odoc_meta;layout_format=0 此节点可跳过/自动通过。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_wenmi\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_9\" name=\"通过\" sourceRef=\"Task_Layout\" targetRef=\"EndEvent_1\" />\n    <endEvent id=\"EndEvent_1\" name=\"归档\">\n      <extensionElements>\n        <wf:node nodeType=\"3\" />\n      </extensionElements>\n    </endEvent>\n  </process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\n    <bpmndi:BPMNPlane id=\"BPMNPlane_1\" bpmnElement=\"odoc_fawen\">\n      <bpmndi:BPMNShape id=\"StartEvent_1_di\" bpmnElement=\"StartEvent_1\">\n        <omgdc:Bounds x=\"100\" y=\"285\" width=\"30\" height=\"30\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Create_di\" bpmnElement=\"Task_Create\">\n        <omgdc:Bounds x=\"160\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_DeptReview_di\" bpmnElement=\"Task_DeptReview\">\n        <omgdc:Bounds x=\"330\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Taohong_di\" bpmnElement=\"Task_Taohong\">\n        <omgdc:Bounds x=\"500\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Countersign_di\" bpmnElement=\"Task_Countersign\">\n        <omgdc:Bounds x=\"670\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Sign_di\" bpmnElement=\"Task_Sign\">\n        <omgdc:Bounds x=\"840\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Seal_di\" bpmnElement=\"Task_Seal\">\n        <omgdc:Bounds x=\"1010\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Finalize_di\" bpmnElement=\"Task_Finalize\">\n        <omgdc:Bounds x=\"1180\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"Task_Layout_di\" bpmnElement=\"Task_Layout\">\n        <omgdc:Bounds x=\"1350\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"EndEvent_1_di\" bpmnElement=\"EndEvent_1\">\n        <omgdc:Bounds x=\"1520\" y=\"285\" width=\"30\" height=\"30\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNEdge id=\"Flow_1_di\" bpmnElement=\"Flow_1\">\n        <omgdi:waypoint x=\"130\" y=\"300\" />\n        <omgdi:waypoint x=\"160\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_2_di\" bpmnElement=\"Flow_2\">\n        <omgdi:waypoint x=\"280\" y=\"300\" />\n        <omgdi:waypoint x=\"330\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_3_di\" bpmnElement=\"Flow_3\">\n        <omgdi:waypoint x=\"450\" y=\"300\" />\n        <omgdi:waypoint x=\"500\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_4_di\" bpmnElement=\"Flow_4\">\n        <omgdi:waypoint x=\"620\" y=\"300\" />\n        <omgdi:waypoint x=\"670\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_5_di\" bpmnElement=\"Flow_5\">\n        <omgdi:waypoint x=\"790\" y=\"300\" />\n        <omgdi:waypoint x=\"840\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_6_di\" bpmnElement=\"Flow_6\">\n        <omgdi:waypoint x=\"960\" y=\"300\" />\n        <omgdi:waypoint x=\"1010\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_7_di\" bpmnElement=\"Flow_7\">\n        <omgdi:waypoint x=\"1130\" y=\"300\" />\n        <omgdi:waypoint x=\"1180\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_8_di\" bpmnElement=\"Flow_8\">\n        <omgdi:waypoint x=\"1300\" y=\"300\" />\n        <omgdi:waypoint x=\"1350\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_9_di\" bpmnElement=\"Flow_9\">\n        <omgdi:waypoint x=\"1470\" y=\"300\" />\n        <omgdi:waypoint x=\"1520\" y=\"300\" />\n      </bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</definitions>\n',1,2109915451397033985,NULL,0,NULL,'1',0,'',0,'000000',NULL,NULL,'2026-10-13 15:53:38',NULL,'2026-10-13 20:10:24',0,0,NULL,3,NULL,NULL,NULL),(2109915581676310530,'odoc_shouwen',2109677533654978561,'收文流程','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:wf=\"http://www.springblade.org/workflow\" xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:flowable=\"http://flowable.org/bpmn\" targetNamespace=\"http://www.springblade.org/workflow\" xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\n  <process id=\"odoc_shouwen\" name=\"收文流程\" isExecutable=\"true\">\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\" />\n    <sequenceFlow id=\"Flow_1\" name=\"提交\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Register\" />\n    <userTask id=\"Task_Register\" name=\"收文登记\" flowable:assignee=\"${initiator}\" flowable:formKey=\"odoc_shouwen_form\">\n      <documentation>创建节点:收文员登记来文,上传正文(docId),填写标题/来文单位/紧急程度/密级/主题词/收文日期;receiveNum 暂隐藏(登记出口自动取号)。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"17\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"urgency\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"secretLevel\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"topicType\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"issuedUnit\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveUnit\" perm=\"0\" visible=\"1\" editable=\"1\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"issueDate\" perm=\"0\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveNum\" perm=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"lwh\" perm=\"2\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"sw\" perm=\"2\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"lwbt\" perm=\"2\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"mj\" perm=\"2\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"zw\" perm=\"2\" required=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"swdw1\" perm=\"3\" required=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"lwdw1\" perm=\"2\" required=\"0\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"syncNodeKeys\":[\"Task_Draft\",\"Task_LeaderApprove\",\"Task_Handle\",\"Task_Circulate\",\"Task_Layout\",\"EndEvent_1\"],\"detailFilterSynced\":true,\"mode\":\"custom\"}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_2\" name=\"提交\" sourceRef=\"Task_Register\" targetRef=\"Task_Draft\" />\n    <userTask id=\"Task_Draft\" name=\"拟办\" flowable:candidateGroups=\"role_office\">\n      <documentation>办公室拟办:提出拟办意见,来文与表单只读。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_office\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"title\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveUnit\" perm=\"2\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveNum\" perm=\"1\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_3\" name=\"通过\" sourceRef=\"Task_Draft\" targetRef=\"Task_LeaderApprove\" />\n    <userTask id=\"Task_LeaderApprove\" name=\"批办\" flowable:candidateGroups=\"role_leader\">\n      <documentation>单位领导批办:明确承办部门与办理要求。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_leader\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveNum\" perm=\"1\" />\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_4\" name=\"通过\" sourceRef=\"Task_LeaderApprove\" targetRef=\"Task_Handle\" />\n    <userTask id=\"Task_Handle\" name=\"承办\" flowable:candidateGroups=\"role_handle\">\n      <documentation>承办部门办理:落实领导批办意见,可退回拟办节点。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"1\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_handle\" bhxj=\"0\" signOrder=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:fieldPerm scope=\"main\" field=\"receiveNum\" perm=\"1\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_5\" name=\"通过\" sourceRef=\"Task_Handle\" targetRef=\"Task_Circulate\" />\n    <userTask id=\"Task_Circulate\" name=\"传阅\" flowable:candidateGroups=\"role_circulate\">\n      <documentation>传阅:向相关单位/人员传阅,signOrder=3 抄送(不需提交)。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"3\" allowReject=\"0\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_circulate\" bhxj=\"0\" signOrder=\"3\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_6\" name=\"通过\" sourceRef=\"Task_Circulate\" targetRef=\"Task_Layout\" />\n    <userTask id=\"Task_Layout\" name=\"转版式归档\" flowable:candidateGroups=\"role_office\">\n      <documentation>转版式:按 wf_odoc_process_set.layout_format 同一 to-layout 接口转 PDF(12)/OFD(13),注入元数据 wf_odoc_meta;layout_format=0 自动通过。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"role_office\" bhxj=\"0\" signOrder=\"0\" />\n          <wf:fieldPerm scope=\"main\" field=\"docId\" perm=\"1\" />\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_7\" name=\"通过\" sourceRef=\"Task_Layout\" targetRef=\"EndEvent_1\" />\n    <endEvent id=\"EndEvent_1\" name=\"归档\">\n      <extensionElements>\n        <wf:node nodeType=\"3\">\n          <wf:extJson>{\"settings\":{\"formContent\":{\"detailFilterSynced\":true,\"mode\":\"custom\",\"mobile\":{}}}}</wf:extJson>\n        </wf:node>\n      </extensionElements>\n    </endEvent>\n  </process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_odoc_shouwen\">\n    <bpmndi:BPMNPlane id=\"BPMNPlane_odoc_shouwen\" bpmnElement=\"odoc_shouwen\">\n      <bpmndi:BPMNShape id=\"BPMNShape_StartEvent_1\" bpmnElement=\"StartEvent_1\">\n        <omgdc:Bounds x=\"100\" y=\"285\" width=\"30\" height=\"30\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"BPMNShape_Task_Register\" bpmnElement=\"Task_Register\">\n        <omgdc:Bounds x=\"160\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"BPMNShape_Task_Draft\" bpmnElement=\"Task_Draft\">\n        <omgdc:Bounds x=\"330\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"BPMNShape_Task_LeaderApprove\" bpmnElement=\"Task_LeaderApprove\">\n        <omgdc:Bounds x=\"500\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"BPMNShape_Task_Handle\" bpmnElement=\"Task_Handle\">\n        <omgdc:Bounds x=\"670\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"BPMNShape_Task_Circulate\" bpmnElement=\"Task_Circulate\">\n        <omgdc:Bounds x=\"840\" y=\"260\" width=\"120\" height=\"80\" />\n      </bpmndi:BPMNShape>\n 