--
-- Table structure for table `workflow_billfield_bak_20261021`
--

DROP TABLE IF EXISTS `workflow_billfield_bak_20261021`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workflow_billfield_bak_20261021` (
  `id` bigint NOT NULL DEFAULT '0' COMMENT '字段ID',
  `billid` bigint DEFAULT NULL COMMENT '所属表单ID',
  `fieldname` varchar(200) DEFAULT NULL COMMENT '字段名',
  `fieldlabel` varchar(500) DEFAULT NULL COMMENT '字段标签（显示名称）',
  `fielddbname` varchar(60) DEFAULT NULL COMMENT '数据库列名',
  `fieldhtmltype` int DEFAULT '1' COMMENT 'HTML表单元素类型(1文本 2多行 3数字 4日期 5下拉 7复选 8单选 10浏览 11附件 14HTML编辑)',
  `fieldtype` int DEFAULT '0' COMMENT '字段类型',
  `fieldlen` int DEFAULT '100' COMMENT '字段长度',
  `decimaldigit` int DEFAULT '0' COMMENT '小数点位数',
  `defaultvalue` varchar(500) DEFAULT NULL COMMENT '默认值',
  `dsporder` int DEFAULT '0' COMMENT '显示顺序',
  `isnull` int DEFAULT '0' COMMENT '是否必填:1是 0否',
  `uniquevalue` int DEFAULT '0' COMMENT '是否唯一:1是 0否',
  `fieldmsg` varchar(500) DEFAULT NULL COMMENT '字段提示',
  `fielddbtype` varchar(50) DEFAULT 'varchar' COMMENT '数据库字段类型',
  `browtype` int DEFAULT NULL COMMENT '浏览框类型',
  `browserurlid` int DEFAULT NULL COMMENT '浏览框URL ID',
  `selectitem` text COMMENT '选项数据(JSON)',
  `detailtable` int DEFAULT NULL COMMENT '关联明细表ID',
  `ismain` int DEFAULT '1' COMMENT '是否主表字段:1是 0否',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(32) DEFAULT '000000' COMMENT '租户ID',
  `textheight` int DEFAULT '4' COMMENT '文本高度（多行文本）',
  `ismand` int DEFAULT '0' COMMENT '是否必填（0否 1是）',
  `fieldorder` int DEFAULT '0' COMMENT '显示顺序',
  `isused` int DEFAULT '1' COMMENT '是否启用（0否 1是）',
  `description` varchar(1000) DEFAULT NULL COMMENT '字段描述',
  `quicktype` int DEFAULT '0' COMMENT '快速录入类型',
  `impcheck` int DEFAULT '0' COMMENT '导入验证类型（0不验证 1电话 2手机 3邮编 4身份证 5日期 6时间 7email 8自定义）',
  `checkexpression` varchar(3000) DEFAULT NULL COMMENT '验证表达式（正则表达式）',
  `placeholder` varchar(1000) DEFAULT NULL COMMENT '提示信息（输入框占位符）',
  `needlog` int DEFAULT '0' COMMENT '是否记录字段修改日志（0否 1是）',
  `is_deleted` int DEFAULT '0' COMMENT '是否删除（0未删除 1已删除）',
  `status` int DEFAULT '1' COMMENT '状态（1正常 0禁用 -1已删除）',
  `dsorder` int DEFAULT '0' COMMENT '排序号',
  `needexcel` int DEFAULT '0' COMMENT '是否允许Excel导入（0否 1是）',
  `isreadonly` int DEFAULT '0' COMMENT '是否只读',
  `issystemfield` int DEFAULT '0' COMMENT '是否系统字段',
  `listdisplay` int DEFAULT '0' COMMENT '是否列表显示'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
